//! Shared, validated genesis configuration for Acton and native Localton.

use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

mod parameters;
pub use parameters::*;
mod validation;
pub use validation::GenesisIssue;
use validation::check;

/// JSON Schema for partial `genesis.toml` documents, generated by `xtask`.
///
/// Editors can use it for completion and shape checks; creation still validates
/// relationships such as election windows and ordered block limits.
pub const GENESIS_SCHEMA_JSON: &str = include_str!("../schemas/genesis.schema.json");

/// Immutable parameters used to create a local TON network.
///
/// CLI, Studio, and native Localton share this schema. Missing TOML fields use
/// local development defaults; unknown fields are errors. Amounts without a
/// fixed-point price unit are whole GRAM. A saved network retains these values
/// independently of the input file and must be recreated to change them.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, ToSchema)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(default, deny_unknown_fields)]
pub struct GenesisConfig {
    /// Negative TON global network identifier
    #[cfg_attr(feature = "schema", schemars(range(max = -1)))]
    pub global_id: i32,
    /// VM protocol version in config parameter 8
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub global_version: u32,
    /// Capability bitmask in config parameter 8
    pub global_capabilities: u64,
    /// Workchain split-depth bounds in config parameter 12
    pub workchain: Workchain,
    /// Storage prices in config parameter 18
    pub storage: StoragePrices,
    /// Workchain gas limits and flat fees in config parameter 21
    pub gas: GasLimits,
    /// Masterchain gas limits and flat fees in config parameter 20
    pub gas_masterchain: GasLimits,
    /// Workchain forwarding prices in config parameter 25
    pub forwarding: ForwardingPrices,
    /// Masterchain forwarding prices in config parameter 24
    pub forwarding_masterchain: ForwardingPrices,
    /// Workchain block limits in config parameter 23
    pub block_limits: BlockLimits,
    /// Masterchain block limits in config parameter 22
    pub masterchain_block_limits: BlockLimits,
    /// Validator rotation and shard assignment in config parameter 28
    pub catchain: Catchain,
    /// Ordinary configuration proposal rules in config parameter 11
    pub voting: Voting,
    /// Critical configuration proposal rules in config parameter 11
    pub critical_voting: Voting,
    /// `true` when the base workchain is enabled
    pub workchain_enabled: bool,
    /// Main genesis wallet balance in GRAM
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub initial_balance: u64,
    /// Balance of each built-in validator wallet in GRAM
    pub validator_wallet_balance: u64,
    /// Stake submitted by genesis validator automation in GRAM
    pub validator_stake: u64,
    /// Faucet wallet balance in GRAM
    pub faucet_balance: u64,
    /// Elector contract balance in GRAM
    pub elector_balance: u64,
    /// Configuration contract balance in GRAM
    pub config_balance: u64,
    /// Workchain gas price in nanograms scaled by 2^16
    pub gas_price: u64,
    /// Masterchain gas price in nanograms scaled by 2^16
    pub gas_price_masterchain: u64,
    /// Workchain forwarding cell price in nanograms scaled by 2^16
    pub cell_price: u64,
    /// Masterchain forwarding cell price in nanograms scaled by 2^16
    pub cell_price_masterchain: u64,
    /// Maximum number of validators
    #[cfg_attr(feature = "schema", schemars(range(min = 1, max = 65535)))]
    pub max_validators: u32,
    /// Maximum number of masterchain validators
    #[cfg_attr(feature = "schema", schemars(range(min = 1, max = 65535)))]
    pub max_masterchain_validators: u32,
    /// Minimum number of validators
    #[cfg_attr(feature = "schema", schemars(range(min = 1, max = 65535)))]
    pub min_validators: u32,
    /// Minimum validator stake in GRAM
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub min_validator_stake: u64,
    /// Maximum validator stake in GRAM
    pub max_validator_stake: u64,
    /// Minimum total validator stake in GRAM
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub min_total_validator_stake: u64,
    /// Maximum stake ratio for one validator
    #[cfg_attr(feature = "schema", schemars(range(min = 1, max = 65535)))]
    pub max_stake_factor: u32,
    /// Validator-set lifetime in seconds
    #[cfg_attr(feature = "schema", schemars(range(min = 4)))]
    pub elected_for_seconds: u32,
    /// Time before the validator-set change when elections start
    pub election_start_before_seconds: u32,
    /// Time before the validator-set change when elections end
    pub election_end_before_seconds: u32,
    /// Stake freeze time in seconds
    pub stakes_frozen_for_seconds: u32,
    /// Original validator-set lifetime in seconds
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub original_validator_set_valid_for_seconds: u32,
    /// Target Simplex block interval stored as noncritical config 30 key 0
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub simplex_target_rate_ms: u32,
    /// Number of slots in one Simplex leader window
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub simplex_slots_per_leader_window: u32,
    /// Timeout for the first block in milliseconds
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub simplex_first_block_timeout_ms: u32,
    /// Maximum number of future Simplex leader windows accepted from peers
    #[cfg_attr(feature = "schema", schemars(range(min = 1)))]
    pub simplex_max_leader_window_desync: u32,
}

impl Default for GenesisConfig {
    fn default() -> Self {
        Self {
            global_id: -3,
            global_version: 15,
            global_capabilities: 0x3ee,
            workchain: Workchain::default(),
            storage: StoragePrices::default(),
            gas: GasLimits::default(),
            gas_masterchain: GasLimits::masterchain(),
            forwarding: ForwardingPrices::default(),
            forwarding_masterchain: ForwardingPrices::masterchain(),
            block_limits: BlockLimits::default(),
            masterchain_block_limits: BlockLimits::default(),
            catchain: Catchain::default(),
            voting: Voting::default(),
            critical_voting: Voting::critical(),
            workchain_enabled: true,
            initial_balance: 4_999_990_000,
            validator_wallet_balance: 50_005,
            validator_stake: 10_001,
            faucet_balance: 1_000_001,
            elector_balance: 10,
            config_balance: 10,
            gas_price: 26_214_400,
            gas_price_masterchain: 655_360_000,
            cell_price: 2_621_440_000,
            cell_price_masterchain: 65_536_000_000,
            max_validators: 1_000,
            max_masterchain_validators: 100,
            min_validators: 1,
            min_validator_stake: 10_000,
            max_validator_stake: 10_000_000,
            min_total_validator_stake: 10_000,
            max_stake_factor: 3,
            elected_for_seconds: 2 * 60,
            election_start_before_seconds: 90,
            election_end_before_seconds: 30,
            stakes_frozen_for_seconds: 30,
            original_validator_set_valid_for_seconds: 90,
            // Localton intentionally runs slower than the current 400ms TON
            // mainnet target so block-by-block debugging remains practical
            simplex_target_rate_ms: 1_000,
            // Keep the remaining consensus shape aligned with masterchain:
            // four slots per leader, a 700ms first-block timeout, and TON's
            // default allowance of 250 future leader windows
            simplex_slots_per_leader_window: 4,
            simplex_first_block_timeout_ms: 700,
            simplex_max_leader_window_desync: 250,
        }
    }
}

impl GenesisConfig {
    /// Loads a partial `genesis.toml` document and validates the resolved defaults.
    pub fn from_toml(source: &str) -> Result<Self> {
        let config = Self::parse_toml(source)?;
        config.validate()?;
        Ok(config)
    }

    /// Resolves a draft for editing without enforcing relationships between fields.
    ///
    /// Syntax, field names, and integer widths are still checked. Callers must use
    /// `validate` before creating a network; editors can display `validation_issues`
    /// while retaining invalid values so the user can correct them.
    pub fn parse_toml(source: &str) -> Result<Self> {
        let overrides: toml::Value = toml::from_str(source).context("invalid genesis.toml")?;
        let mut values = toml::Value::try_from(Self::default())?;
        merge_values(&mut values, overrides);
        serde_path_to_error::deserialize(values)
            .map_err(|error| GenesisIssue {
                fields: vec![error.path().to_string()],
                message: error.inner().message().to_owned(),
            })
            .context("invalid genesis.toml")
    }

    /// Exports the complete configuration, including all resolved defaults.
    pub fn to_toml(&self) -> Result<String> {
        toml::to_string_pretty(self).context("genesis values cannot be represented in TOML")
    }

    /// Applies explicit CLI timing overrides before validating the final genesis.
    pub fn with_timing(
        mut self,
        block_time: Option<u32>,
        election_time: Option<u32>,
    ) -> Result<Self> {
        if let Some(value) = block_time {
            self.simplex_target_rate_ms = value;
        }
        if let Some(value) = election_time {
            self.set_election_time_seconds(value)?;
        }
        self.validate()?;
        Ok(self)
    }

    /// Configures a validator round and its dependent genesis timings
    ///
    /// TON config parameter 15 expresses the election window relative to the
    /// validator-set change. Localton opens the window after one quarter of the
    /// round has elapsed, closes it one quarter before the change, and uses the
    /// same quarter for stake freezing. The initial validator-set lifetime equals
    /// the opening offset, which lets the first election begin immediately
    pub fn set_election_time_seconds(&mut self, election_time_seconds: u32) -> Result<()> {
        ensure!(
            election_time_seconds >= 4,
            "election time must be at least 4 seconds"
        );

        let quarter = election_time_seconds / 4;
        let election_start_before = election_time_seconds - quarter;
        self.elected_for_seconds = election_time_seconds;
        self.election_start_before_seconds = election_start_before;
        self.election_end_before_seconds = quarter;
        self.stakes_frozen_for_seconds = quarter;
        self.original_validator_set_valid_for_seconds = election_start_before;
        Ok(())
    }

    /// Checks protocol widths and relationships before any network is created.
    pub fn validate(&self) -> Result<()> {
        if let Some(issue) = self.validation_issues().into_iter().next() {
            return Err(issue.into());
        }
        // JSON callers must also fit the signed TOML range to allow lossless export.
        self.to_toml()?;
        Ok(())
    }

    /// Lists all failed relationships with the editable fields involved in each one.
    ///
    /// Editors use this on drafts. Creation must still call `validate`, which also
    /// checks that every accepted value can be exported to TOML.
    #[must_use]
    pub fn validation_issues(&self) -> Vec<GenesisIssue> {
        let mut issues = Vec::new();
        check(
            &mut issues,
            self.elected_for_seconds >= 4,
            "",
            &["elected_for_seconds"],
            "Validator round duration must be at least 4 s",
        );
        check(
            &mut issues,
            self.validator_stake >= self.min_validator_stake
                && self.validator_stake <= self.max_validator_stake,
            "",
            &[
                "validator_stake",
                "min_validator_stake",
                "max_validator_stake",
            ],
            "Validator stake must be between the minimum and maximum validator stakes",
        );
        check(
            &mut issues,
            self.validator_wallet_balance <= u64::MAX / 1_000_000_000,
            "",
            &["validator_wallet_balance"],
            "Validator wallet balance exceeds the supported amount",
        );
        check(
            &mut issues,
            self.validator_stake
                .checked_add(5)
                .is_some_and(|minimum| self.validator_wallet_balance >= minimum),
            "",
            &["validator_wallet_balance", "validator_stake"],
            "Validator wallet balance must cover the validator stake plus a 5 GRAM fee reserve",
        );
        check(
            &mut issues,
            self.min_validators > 1 || self.validator_stake >= self.min_total_validator_stake,
            "",
            &[
                "validator_stake",
                "min_total_validator_stake",
                "min_validators",
            ],
            "Validator stake must cover the minimum total stake when the network has one validator",
        );
        check(
            &mut issues,
            self.global_version > 0,
            "",
            &["global_version"],
            "Protocol version must be greater than zero",
        );
        check(
            &mut issues,
            self.global_capabilities <= i64::MAX as u64,
            "",
            &["global_capabilities"],
            "Protocol capabilities exceed the supported integer range",
        );
        check(
            &mut issues,
            self.max_validators <= u16::MAX.into(),
            "",
            &["max_validators"],
            "Maximum validator count must not exceed 65,535",
        );
        check(
            &mut issues,
            self.max_stake_factor > 0 && self.max_stake_factor <= u16::MAX.into(),
            "",
            &["max_stake_factor"],
            "Maximum stake factor must be between 1 and 65,535",
        );
        check(
            &mut issues,
            self.initial_balance > 0,
            "",
            &["initial_balance"],
            "Initial balance must be greater than zero",
        );
        for (key, value) in [
            ("min_validator_stake", self.min_validator_stake),
            ("min_total_validator_stake", self.min_total_validator_stake),
        ] {
            check(
                &mut issues,
                value > 0,
                "",
                &[key],
                "Minimum validator stakes must be greater than zero",
            );
        }
        check(
            &mut issues,
            self.original_validator_set_valid_for_seconds > 0,
            "",
            &["original_validator_set_valid_for_seconds"],
            "Initial validator set lifetime must be greater than zero",
        );
        self.workchain.validation_issues(&mut issues);
        self.gas
            .validation_issues(&mut issues, "gas", "Workchain gas");
        self.gas_masterchain
            .validation_issues(&mut issues, "gas_masterchain", "Masterchain gas");
        self.block_limits
            .validation_issues(&mut issues, "block_limits", "Workchain block limits");
        self.masterchain_block_limits.validation_issues(
            &mut issues,
            "masterchain_block_limits",
            "Masterchain block limits",
        );
        self.catchain.validation_issues(&mut issues);
        self.voting
            .validation_issues(&mut issues, "voting", "Configuration voting");
        self.critical_voting.validation_issues(
            &mut issues,
            "critical_voting",
            "Critical configuration voting",
        );
        check(
            &mut issues,
            self.global_id < 0,
            "",
            &["global_id"],
            "Network ID must be negative",
        );
        check(
            &mut issues,
            self.min_validators > 0,
            "",
            &["min_validators"],
            "Minimum validator count must be greater than zero",
        );
        check(
            &mut issues,
            self.min_validators <= self.max_masterchain_validators
                && self.max_masterchain_validators <= self.max_validators,
            "",
            &[
                "min_validators",
                "max_masterchain_validators",
                "max_validators",
            ],
            "Validator counts must follow: minimum ≤ masterchain maximum ≤ network maximum",
        );
        check(
            &mut issues,
            self.min_validator_stake <= self.max_validator_stake,
            "",
            &["min_validator_stake", "max_validator_stake"],
            "Minimum validator stake must not exceed maximum validator stake",
        );
        check(
            &mut issues,
            self.election_end_before_seconds < self.election_start_before_seconds,
            "",
            &[
                "election_end_before_seconds",
                "election_start_before_seconds",
            ],
            format!(
                "Elections must close closer to the round end than they start: close offset {} s ≥ start offset {} s",
                self.election_end_before_seconds, self.election_start_before_seconds
            ),
        );
        check(
            &mut issues,
            self.election_start_before_seconds < self.elected_for_seconds,
            "",
            &["election_start_before_seconds", "elected_for_seconds"],
            format!(
                "Elections start offset must be less than the validator round duration: {} s ≥ {} s",
                self.election_start_before_seconds, self.elected_for_seconds
            ),
        );
        for (key, value) in [
            ("simplex_target_rate_ms", self.simplex_target_rate_ms),
            (
                "simplex_slots_per_leader_window",
                self.simplex_slots_per_leader_window,
            ),
            (
                "simplex_first_block_timeout_ms",
                self.simplex_first_block_timeout_ms,
            ),
            (
                "simplex_max_leader_window_desync",
                self.simplex_max_leader_window_desync,
            ),
        ] {
            check(
                &mut issues,
                value > 0,
                "",
                &[key],
                "Consensus intervals, timeouts, and leader window limits must be greater than zero",
            );
        }
        issues
    }
}

// Merge before deserialization so partial masterchain sections retain their own
// defaults instead of inheriting the workchain defaults of a shared Rust type.
fn merge_values(target: &mut toml::Value, source: toml::Value) {
    match (target, source) {
        (toml::Value::Table(target), toml::Value::Table(source)) => {
            for (key, value) in source {
                if let Some(existing) = target.get_mut(&key) {
                    merge_values(existing, value);
                } else {
                    target.insert(key, value);
                }
            }
        }
        (target, source) => *target = source,
    }
}
